using TinyBlueWhale.MiniBus;
using MediatR;
namespace MiniBus.Benchmarks.Handlers;
public record Request0(int Id) :
    MediatR.IRequest<int>,
    TinyBlueWhale.MiniBus.IRequest<int>;
public class Request0Handler :
    MediatR.IRequestHandler<Request0, int>,
    TinyBlueWhale.MiniBus.IRequestHandler<Request0, int>
{
    public Task<int> Handle(Request0 request, CancellationToken cancellationToken)
        => Task.FromResult(request.Id);
    Task<int> MediatR.IRequestHandler<Request0, int>.Handle(
        Request0 request,
        CancellationToken cancellationToken)
        => Handle(request, cancellationToken);
}
